Creates a message with a sender, a recipient and an attachment, saves it to an in-memory byte buffer with mapi_message::save, reloads it from those bytes with mapi_message::from_stream and checks the subject, sender, recipient count and attachment filename on the reloaded copy.

Example:
#include <fstream>
// Authored example: create a message, save it to memory, and reload it from the saved bytes.
#include <cassert>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "aspose/email/foss/msg/mapi_message.hpp"

using aspose::email::foss::msg::mapi_message;

int main()
{
    auto message = mapi_message::create("Weekly digest", "See attached notes.");
    message.set_sender_name("Dana Ops");
    message.set_sender_email_address("dana@example.com");
    message.add_recipient("eve@example.com", "Eve Example");
    message.add_attachment("notes.txt", std::vector<std::uint8_t> {'h', 'i'}, "text/plain");

    const auto bytes = message.save();
    const std::string blob(bytes.begin(), bytes.end());
    std::istringstream stream(blob);
    auto loaded = mapi_message::from_stream(stream);

    std::cout << "subject: " << loaded.subject() << '\n';
    std::cout << "sender: " << loaded.sender_name() << " <" << loaded.sender_email_address() << ">\n";
    std::cout << "recipients: " << loaded.recipients().size() << '\n';
    std::cout << "attachments: " << loaded.attachments().size() << '\n';

    assert(loaded.subject() == "Weekly digest");
    assert(loaded.sender_name() == "Dana Ops");
    assert(loaded.recipients().size() == 1);
    assert(loaded.attachments().size() == 1);
    assert(loaded.attachments()[0].filename == "notes.txt");
    return 0;
}
