Creates a message with two recipients and an attachment, saves it, re-reads the saved bytes at the low level with msg_reader::from_stream and msg_document::from_reader, and counts the recipient and attachment storages under the MSG document's root, checking the reader reported no validation issues.

Example:
#include <fstream>
// Authored example: dump the low-level MSG storage tree of a saved message.
#include <cassert>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "aspose/email/foss/msg/mapi_message.hpp"
#include "aspose/email/foss/msg/msg_document.hpp"
#include "aspose/email/foss/msg/msg_reader.hpp"
#include "aspose/email/foss/msg/msg_storage_role.hpp"

using aspose::email::foss::msg::mapi_message;
using aspose::email::foss::msg::msg_document;
using aspose::email::foss::msg::msg_reader;
using aspose::email::foss::msg::msg_storage_role;

int main()
{
    auto message = mapi_message::create("Shipping confirmation", "Your order has shipped.");
    message.add_recipient("f@example.com", "Frank Example");
    message.add_recipient("g@example.com", "Grace Example");
    message.add_attachment("label.txt", std::vector<std::uint8_t> {'L'}, "text/plain");

    const auto bytes = message.save();
    const std::string blob(bytes.begin(), bytes.end());
    std::istringstream stream(blob);

    const auto reader = msg_reader::from_stream(stream);
    const auto document = msg_document::from_reader(reader);
    const auto& root = document.root();

    std::size_t recipient_storages = 0;
    std::size_t attachment_storages = 0;
    for (const auto& storage : root.storages)
    {
        if (storage.role == msg_storage_role::recipient)
        {
            ++recipient_storages;
        }
        else if (storage.role == msg_storage_role::attachment)
        {
            ++attachment_storages;
        }
    }

    std::cout << "validation_issues: " << reader.validation_issues().size() << '\n';
    std::cout << "recipient_storages: " << recipient_storages << '\n';
    std::cout << "attachment_storages: " << attachment_storages << '\n';

    assert(reader.validation_issues().empty());
    assert(recipient_storages == 2);
    assert(attachment_storages == 1);
    return 0;
}
