Builds a Compound File Binary container directly from cfb_storage and cfb_stream nodes, serialises it to bytes with cfb_writer::to_bytes, re-parses those bytes with cfb_reader::from_bytes and walks the resulting directory_entry tree to find the stream by name and check its payload byte-for-byte.

Example:
#include <fstream>
#include "aspose/email/foss/msg/mapi_message.hpp"
// Authored example: build a CFB container from scratch and read it back with cfb_reader.
#include <cassert>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

#include "aspose/email/foss/cfb/cfb_document.hpp"
#include "aspose/email/foss/cfb/cfb_reader.hpp"
#include "aspose/email/foss/cfb/cfb_storage.hpp"
#include "aspose/email/foss/cfb/cfb_stream.hpp"
#include "aspose/email/foss/cfb/cfb_writer.hpp"
#include "aspose/email/foss/cfb/directory_entry.hpp"

using namespace aspose::email::foss::cfb;

int main()
{
    cfb_storage root("Root Entry");
    const std::vector<std::uint8_t> payload {'p', 'a', 'y', 'l', 'o', 'a', 'd'};
    root.add_stream(cfb_stream("MyStream", payload));

    cfb_document document(std::move(root));
    const auto bytes = cfb_writer::to_bytes(document);
    std::cout << "written bytes: " << bytes.size() << '\n';

    const auto reader = cfb_reader::from_bytes(bytes);
    const aspose::email::foss::cfb::directory_entry& top = reader.root_entry();
    assert(top.is_root());

    bool found = false;
    for (const auto child_id : reader.child_ids(top.stream_id))
    {
        const aspose::email::foss::cfb::directory_entry& entry = reader.get_entry(child_id);
        if (entry.name == "MyStream")
        {
            found = true;
            const auto& data = reader.get_stream_data(child_id);
            std::cout << "MyStream size: " << data.size() << '\n';
            assert(data == payload);
        }
    }

    assert(found);
    return 0;
}
