Sets an arbitrary MAPI property by numeric id and type with mapi_message::set_property, reads it back two ways through mapi_message::get_property_value and through the message's own property collection, and checks both the decoded value and the stored property's combined property_tag.

Example:
#include <fstream>
// Authored example: set and read an arbitrary MAPI property by id and type.
#include <any>
#include <cassert>
#include <iostream>
#include <string>
#include <type_traits>

#include "aspose/email/foss/msg/common_message_property_id.hpp"
#include "aspose/email/foss/msg/mapi_message.hpp"
#include "aspose/email/foss/msg/property_type_code.hpp"

namespace
{
template <typename Enum>
constexpr auto to_underlying(const Enum value) noexcept
{
    return static_cast<std::underlying_type_t<Enum>>(value);
}
} // namespace

using aspose::email::foss::msg::common_message_property_id;
using aspose::email::foss::msg::mapi_message;
using aspose::email::foss::msg::property_type_code;

int main()
{
    auto message = mapi_message::create("Build notification", "The nightly build passed.");
    message.set_property(
        to_underlying(common_message_property_id::internet_message_id),
        to_underlying(property_type_code::ptyp_string),
        std::string("<nightly-001@example.com>"));

    const auto* stored = message.get_property_value(
        to_underlying(common_message_property_id::internet_message_id),
        to_underlying(property_type_code::ptyp_string));
    assert(stored != nullptr);
    const auto message_id = std::any_cast<std::string>(*stored);
    std::cout << "internet_message_id: " << message_id << '\n';

    auto& collection = message.properties();
    const auto* entry = collection.get(
        to_underlying(common_message_property_id::internet_message_id),
        to_underlying(property_type_code::ptyp_string));
    assert(entry != nullptr);
    std::cout << "property_tag: 0x" << std::hex << entry->property_tag() << std::dec << '\n';

    assert(message_id == "<nightly-001@example.com>");
    return 0;
}
